CREATE TRIGGER RefCusRateUOM_Combined
	ON RefCusRateUOM
	FOR INSERT, UPDATE, DELETE
	AS
	IF (SELECT CASE WHEN EXISTS(SELECT 1 FROM INSERTED) AND NOT EXISTS(SELECT 1 FROM DELETED) THEN 1 ELSE 0 end) = 1
	BEGIN
		UPDATE t SET
		ZXG_DataSetPK = ZZ2_DataSetPK,
		ZXG_DataSetCode = ZZ2_DataSetCode
		FROM RefCusRateUOM t
		JOIN inserted ON t.ZXG_PK = inserted.ZXG_PK
		LEFT JOIN RefCusRate ON inserted.ZXG_ZZ2_Rate = ZZ2_PK
	END

	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT t.ZXG_DataSetPK, t.ZXG_DataSetCode
	FROM RefCusRateUOM t
	JOIN inserted ON t.ZXG_PK = inserted.ZXG_PK
	UNION
	SELECT ZXG_DataSetPK, ZXG_DataSetCode
	FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

CREATE TRIGGER RefCusRateUOM_DataProcessingResult_Delete
	ON RefCusRateUOM
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.ZXG_PK
	END
GO
